head.script:
scwin.btn_disabled_true_onclick = function (e) {
    grp_normal.setDisabled(true);
    sv_defect.setDisabled(true);
    scwin.setReturnValue("setDisabled(true)");
};

scwin.btn_disabled_false_onclick = function (e) {
    grp_normal.setDisabled(false);
    sv_defect.setDisabled(false);
    scwin.setReturnValue("setDisabled(false)");
};

scwin.btn_readonly_true_onclick = function (e) {
    grp_normal.setReadOnly(true);
    sv_defect.setReadOnly(true);
    scwin.setReturnValue("setReadOnly(true)");
};

scwin.btn_readonly_false_onclick = function (e) {
    grp_normal.setReadOnly(false);
    sv_defect.setReadOnly(false);
    scwin.setReturnValue("setReadOnly(false)");
};

scwin.btn_check_onclick = function (e) {
    scwin.setReturnValue("[group] getDisabled=" + grp_normal.getDisabled()
        + " / input.getDisabled=" + ibx_normal.getDisabled()
        + " / button.getDisabled=" + btn_normal.getDisabled()
        + " / getReadOnly=" + grp_normal.getReadOnly()
        + " / input.getReadOnly=" + ibx_normal.getReadOnly());
    scwin.setReturnValue("[scrollView] getDisabled=" + sv_defect.getDisabled()
        + " / input.getDisabled=" + ibx_defect.getDisabled()
        + " / button.getDisabled=" + btn_defect.getDisabled()
        + " / getReadOnly=" + sv_defect.getReadOnly()
        + " / input.getReadOnly=" + ibx_defect.getReadOnly());
};

scwin.btn_normal_onclick = function (e) {
    scwin.setReturnValue("[group] button onclick 발생");
};

scwin.btn_defect_onclick = function (e) {
    scwin.setReturnValue("[scrollView] button onclick 발생");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
